!function(i){function r(r){for(var n,t,o=r[0],m=r[1],g=r[2],u=0,c=[];u<o.length;u++)t=o[u],Object.prototype.hasOwnProperty.call(p,t)&&p[t]&&c.push(p[t][0]),p[t]=0;for(n in m)Object.prototype.hasOwnProperty.call(m,n)&&(i[n]=m[n]);for(s&&s(r);c.length;)c.shift()();return e.push.apply(e,g||[]),a()}function a(){for(var i,r=0;r<e.length;r++){for(var a,t=e[r],o=!0,m=1;m<t.length;m++)a=t[m],0!==p[a]&&(o=!1);o&&(e.splice(r--,1),i=n(n.s=t[0]))}return i}function n(r){if(t[r])return t[r].exports;var a=t[r]={i:r,l:!1,exports:{}};return i[r].call(a.exports,a,a.exports,n),a.l=!0,a.exports}var t={},p={14:0},e=[];n.m=i,n.c=t,n.d=function(i,r,a){n.o(i,r)||Object.defineProperty(i,r,{enumerable:!0,get:a})},n.r=function(i){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(i,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(i,"__esModule",{value:!0})},n.t=function(i,r){if(1&r&&(i=n(i)),8&r)return i;if(4&r&&"object"==typeof i&&i&&i.__esModule)return i;var a=Object.create(null);if(n.r(a),Object.defineProperty(a,"default",{enumerable:!0,value:i}),2&r&&"string"!=typeof i)for(var t in i)n.d(a,t,function(r){return i[r]}.bind(null,t));return a},n.n=function(i){var r=i&&i.__esModule?function(){return i.default}:function(){return i};return n.d(r,"a",r),r},n.o=function(i,r){return Object.prototype.hasOwnProperty.call(i,r)},n.p="";var o=window.webpackJsonp=window.webpackJsonp||[],m=o.push.bind(o);o.push=r,o=o.slice();for(var g=0;g<o.length;g++)r(o[g]);var s=m;e.push([72,0]),a()}({72:function(i,r,a){"use strict";a.r(r);var n=a(0);Object(n.a)("ru","army",a(73),a(1))},73:function(i){i.exports=JSON.parse('{"category":[{"name":"苏联","link":"ru_shortcut"},{"name":"陆战武器","link":"ru_army"},{"name":"轻武器","link":"ru_army#ru_army_iw"}],"model":"莫辛·纳甘式步枪","description":"<h6>综述：</h6><p>莫辛·纳甘式步枪是在沙俄时期由俄国莫辛上校和比利时枪械师纳甘共同设计的一种手动步枪，型号为莫辛·纳甘1891式步枪，后在苏联时代的1930年进行了较大改进，改型为莫辛·纳甘1891/30式步枪，并正式装备苏联红军，在二战期间，为了满足骑兵等其它兵种的需求，先后将莫辛·纳甘1891/30式步枪改造为长度较短的步骑枪和卡宾枪。</p><p>二战期间，莫辛·纳甘1891/30式步枪是苏军步兵的主要武器装备，在东线各战场上，都可见到苏军步兵持莫辛·纳甘1891/30式步枪作战的身影，更为突出的是装上瞄准器的莫辛·纳甘1891/30式步枪成为苏军狙击手的利器，在苏德战场上对德军造成了极大的威胁。而用该步枪改造的步骑枪、卡宾枪其后也在苏军步兵、骑兵和炮兵等各部队中大量装备，在战斗中发挥了重要作用。</p><p>莫辛·纳甘步枪的产量十分大，有统计称在二战结束前苏联就已生产了1700多万支，在二战结束后，该枪还在继续大量生产，并出口至多国军队使用。</p>","part1title":"系列型号","part1description":"","part1content":[{"image":"imgs/ru/army/ru_army_iwMosinNagant_10.jpg","description":"<h6>莫辛·纳甘1891/30式步枪</h6><p></p><p>基本技术数据：</p><p>枪口径：7.62毫米；</p><p>枪全长：1232毫米，枪管长：730毫米；</p><p>枪重量：4公斤；</p><p>枪口初速：865米/秒；</p><p>有效射程：800米；</p><p>弹匣容量：5发。</p>","caption":""},{"image":"imgs/ru/army/ru_army_iwMosinNagant_11.jpg","description":"<h6>莫辛·纳甘1938式与1944式卡宾枪</h6><p></p><p>基本技术数据：</p><p>枪口径：7.62毫米；</p><p>枪全长：1016毫米；枪管长：38式508毫米，44式517毫米（带刺刀全长1327毫米）；</p><p>枪重量：38式3.47公斤，44式3.9公斤；</p><p>枪口初速：38式766米/秒，44式820米/秒；</p><p>弹匣容量：5发。</p>","caption":""}],"part2title":"战场上的莫辛·纳甘式步枪","part2description":"","part2content":[{"image":"imgs/ru/army/ru_army_iwMosinNagant_20.jpg","description":"（图左）1940年，一名肩背莫辛·纳甘1891/30式步枪的苏军第609步兵团列兵。（图中）1943年，一名手持莫辛·纳甘1891/30式步枪的苏军第253步兵团列兵。（图右）1940年冬季，一名手持莫辛·纳甘1891/30式步枪的苏军第37步兵团列兵。","caption":""},{"image":"imgs/ru/army/ru_army_iwMosinNagant_21.jpg","description":"（图左）1942年，一名肩背莫辛·纳甘1938式卡宾枪的苏军第8空降旅第4营伞兵。（图中）1941年，一名手持带刺刀的莫辛·纳甘1891/30式步枪的苏军老兵。（图右）1943年，一名手持带刺刀的莫辛·纳甘1891/30式步枪的苏联黑海舰队海军士兵。","caption":""},{"image":"imgs/ru/army/ru_army_iwMosinNagant_22.jpg","description":"（图左）1944年，一名手持莫辛·纳甘1944式卡宾枪的苏军第4步兵团列兵。（图中）1944年，一名手持莫辛·纳甘1944式卡宾枪的苏军摩托化步兵营中尉。（图右）1941年，一名手持莫辛·纳甘1938式卡宾枪的苏军第65骑兵团上尉。","caption":""},{"image":"imgs/ru/army/ru_army_iwMosinNagant_23.jpg","description":"（图左）1941年，一名手持莫辛·纳甘1891/30式步枪作刺杀准备的苏军第321步兵团列兵。（图右）1941年，一名手持莫辛·纳甘1891/30式步枪作冲锋状的苏军第129步兵师士兵。","caption":""},{"image":"imgs/ru/army/ru_army_iwMosinNagant_24.jpg","description":"二战东线苏联战场上，两名手持莫辛·纳甘1891/30式狙击步枪的苏军女狙击手，她们胸前戴着杀敌立功的勋章。这些女狙击手在苏联卫国战争的战场上十分出名，不少德军都倒在了她们精准的枪击下。其中图右的女狙击手是罗莎·莎妮娜中士，曾用莫辛·纳甘1891/30式狙击步枪创下了击杀54名德军的战绩，荣获2级和3级勋章各一枚。","caption":""},{"image":"imgs/ru/army/ru_army_iwMosinNagant_25.jpg","description":"二战东线苏联战场上，两名年轻漂亮的苏军女狙击手，她们手持莫辛·纳甘1891/30式狙击步枪，脸上充满自信与笑容。","caption":""},{"image":"imgs/ru/army/ru_army_iwMosinNagant_26.jpg","description":"1942年，东线苏联战场，在斯大林格勒保卫战初期，手持莫辛·纳甘1891/30式步枪的苏军步兵与德军进行殊死的城区争夺战。","caption":""},{"image":"imgs/ru/army/ru_army_iwMosinNagant_27.jpg","description":"1942年10月，东线苏联战场，在斯大林格勒保卫战中，工人民兵营的战士手持莫辛·纳甘1891/30式步枪坚守在一处废墟阵地上。","caption":""},{"image":"imgs/ru/army/ru_army_iwMosinNagant_28.jpg","description":"1942年4月，东线苏联战场库尔斯克地区，在一名手持莫辛·纳甘1891/30式步枪的苏军步兵掩护下，苏联西南方面军第21集团军第526工兵营士兵正在进行剪铁丝网的战前演习。","caption":""},{"image":"imgs/ru/army/ru_army_iwMosinNagant_29.jpg","description":"1942年3月，东线苏联战场，一个苏军步兵班的战士用橡皮筏和小木船悄悄渡过一条河流，他们都手持着莫辛·纳甘1891/30式步枪，准备对德军进行偷袭。","caption":""},{"image":"imgs/ru/army/ru_army_iwMosinNagant_30.jpg","description":"1941年7月，东线苏联战场，一队苏军步兵正徒步赶往前线抵挡进攻的德军。在苏联卫国战争初期，苏军的装备还是比较落后的，队伍中除了一名战士扛着一挺机枪外，其它战士装备的都是莫辛·纳甘1891/30式步枪。","caption":""},{"image":"imgs/ru/army/ru_army_iwMosinNagant_31.jpg","description":"1942年春天，东线苏联战场库尔斯克地区的苏军一处57毫米反坦克炮阵地上，两名持莫辛·纳甘1891/30式步枪作掩护的战士。","caption":""},{"image":"imgs/ru/army/ru_army_iwMosinNagant_32.jpg","description":"1941年9月，东线苏联战场列宁格勒地区，列宁格勒民兵师战士正埋伏在涅瓦河沿岸高地挖出的散兵坑阵地中，持莫辛·纳甘1891/30式步枪阻击进攻的德军。在列宁格勒保卫战中，这些临时组建的民兵师发挥了至关重要的作用，在庞大的德军装甲集群面前，他们不惧牺牲，大大减慢了德军在列宁格勒的推进速度。","caption":""},{"image":"imgs/ru/army/ru_army_iwMosinNagant_33.jpg","description":"1941年，东线苏联战场，一支苏军部队正与德军争夺一处山头阵地，手持莫·纳甘1891/30式步枪的苏军士兵不畏牺牲，奋勇向山顶冲去。","caption":""},{"image":"imgs/ru/army/ru_army_iwMosinNagant_34.jpg","description":"二战东线苏联战场，苏军一个马克沁重机枪组在与德军战斗中，机枪射手身上背着一支1938式莫辛·纳甘卡宾枪。由于卡宾枪长度较短，重量也稍轻，适合机枪手在近战时作自卫用。","caption":""},{"image":"imgs/ru/army/ru_army_iwMosinNagant_35.jpg","description":"绘画：二战东线苏联战场，手持莫辛·纳甘1891/30式步枪、不畏牺牲冲锋杀敌的苏军战士。","caption":""},{"image":"imgs/ru/army/ru_army_iwMosinNagant_36.jpg","description":"二战东线苏联战场，苏军狙击手蒂托夫正在检查安装在莫辛·纳甘1891/30式狙击步枪上的PE瞄准镜（4倍的PE瞄准镜重0.62公斤，最大瞄距为1400米）。莫辛·纳甘1891/30式狙击步枪在二战前已大量装备苏军狙击手，在二战狙击手战绩的前48排名中，除了1名芬兰人和5名德国人外，其余都是苏军士兵，其中还有不少苏军女兵。","caption":""},{"image":"imgs/ru/army/ru_army_iwMosinNagant_37.jpg","description":"二战东线苏联战场，一个苏军狙击小组埋伏在草丛中，持莫辛·纳甘1891/30式狙击步枪执行猎杀德军的任务。","caption":""},{"image":"imgs/ru/army/ru_army_iwMosinNagant_38.jpg","description":"二战东线苏联战场，一名使用莫辛·纳甘1891/30式狙击步枪的苏联海军陆战队狙击手，该枪上安装的是PEM瞄准器（它是PE瞄准镜的改良型号，主要是简化了生产工序和改善了镜体密封性。这种狙击枪首次使用是在1939年至1940年的苏芬战争）。","caption":""},{"image":"imgs/ru/army/ru_army_iwMosinNagant_39.jpg","description":"1942年冬季，东线苏联战场，苏联加里宁方面军的狙击手，近卫军中士亚里姆库克正持一支莫辛·纳甘1891/30式狙击步枪在雪地中等待猎物。二战中，苏军有很多著名的狙击手，但最早表现突出的却是芬兰士兵，在苏芬战争中，芬兰的狙击手使用本国制造的莫辛·纳甘式狙击步枪与滑雪板的高机动结合起来，以其猎人的出身与地形的熟悉，用精准射击使苏军遭到大量伤亡。其中一个号称“白色死神”的芬兰人西蒙·海耶，更是在四个月的时间内，用不配瞄准镜的莫辛·纳甘式狙击步枪击毙了505名苏军士兵，成为二战的狙击之王。这次大亏引起苏军的高度重视，促使苏军在后来的苏德战争中涌现出了大批优秀狙击手。","caption":""},{"image":"imgs/ru/army/ru_army_iwMosinNagant_40.jpg","description":"绘画：二战东线战场，跟随苏军装甲部队反攻的苏军战士，士兵手持的是莫辛·纳甘1891/30式步枪。在二战后期，尽管苏军已大量装备冲锋枪和半自动步枪，但莫辛·纳甘1891/30式步枪仍未淘汰，依旧给苏军步兵装备使用。","caption":""},{"image":"imgs/ru/army/ru_army_iwMosinNagant_41.jpg","description":"一张苏联卫国战争时期的宣传画，前景是一名手持莫辛·纳甘1891/30式步枪的苏军战士。","caption":""}]}')}});